                    int pivotCol = d;
                    double maxNorm1 = diagNorm1;
                    for (int c = d + 1; c < n; c++)
                        if (vn1p[c] > maxNorm1) { maxNorm1 = vn1p[c]; pivotCol = c; }

                    // Tie guard (see decompInPlaceCore): only pivot past accumulated rounding noise.
                    if (pivotCol != d && maxNorm1 > diagNorm1 * pivotRelTolRoot)
                    {
                        Swap.Columns(ref A_to_Q, d, pivotCol);   // full column: carries the R prefix too
                        P.Swap(d, pivotCol);
                        double tv1 = vn1p[d]; vn1p[d] = vn1p[pivotCol]; vn1p[pivotCol] = tv1;
                        double tv2 = vn2p[d]; vn2p[d] = vn2p[pivotCol]; vn2p[pivotCol] = tv2;
                        // Swap the k already-filled F rows (columns 0..k-1) for the two A-columns —
                        // panel-local rows k (the pivot slot) and pivotCol-p0.
                        int jlp = pivotCol - p0;
                        double* Frk = Fp + (long)k * QRCP_BLOCK;
                        double* Frp = Fp + (long)jlp * QRCP_BLOCK;
                        for (int i = 0; i < k; i++) { double tf = Frk[i]; Frk[i] = Frp[i]; Frp[i] = tf; }
                    }

                    // --- 2. bring the pivot column up to date: A[r,d] −= Σ_{i<k} u_i[r]·F[k,i] ---
                    //     u_i is stored in A[:, p0+i]; F row k is contiguous. Rows [rk, m) only (rows
                    //     above rk are finished R entries, already made true by prior row updates).
                    if (k > 0)
                    {
                        double* Frk = Fp + (long)k * QRCP_BLOCK;
                        for (int r = rk; r < m; r++)
                        {
                            double* Aseg = Ap + (long)r * n + p0;   // A[r, p0 + i]
                            double s = (double)0;
                            for (int i = 0; i < k; i++)
                                s += Aseg[i] * Frk[i];
                            Aseg[k] -= s;                            // Aseg[k] == A[r, d]
                        }
                    }

                    // --- 3. Householder reflector for the (now up-to-date) column d ---
                    QR.genHouseholder(ref A_to_Q, ref u, d, zeroThreshold);

                    // --- 4. R[d,d] = reflector applied to its own column, then store the reflector ---
                    //     beta = uᵀ·col_d (ascending rows) ⇒ R[d,d] = A[d,d] − u[d]·beta, matching what
                    //     applyReflectorRight would write. col_d still holds the original data here.
                    double beta = (double)0;
                    for (int r = d; r < m; r++)
                        beta += up[r] * Ap[(long)r * n + d];
                    R[d, d] = A_to_Q[d, d] - up[d] * beta;
                    for (int r = d; r < m; r++)
                        Ap[(long)r * n + d] = up[r];

                    // --- fused solve: apply this reflector to b (b -= u·(uᵀb), rows [d, m)) so b
                    //     accumulates Qᵀb as reflectors are generated — no Q ever formed. ---
                    if (fusedSolve)
                    {
                        if (nrhs == 1)
                        {
                            double dotb = (double)0;
                            for (int r = d; r < m; r++)
                                dotb += up[r] * bp[r];
                            for (int r = d; r < m; r++)
                                bp[r] -= up[r] * dotb;
                        }
                        else
                        {
                            UnsafeUtility.MemClear(rhsAccp, (long)nrhs * UnsafeUtility.SizeOf<double>());
                            for (int r = d; r < m; r++)
                                UnsafeOP.axpy(rhsAccp, bp + (long)r * nrhs, up[r], nrhs);
                            for (int r = d; r < m; r++)
                                UnsafeOP.axpy(bp + (long)r * nrhs, rhsAccp, -up[r], nrhs);
                        }
                    }

                    // --- 5. one combined pass acc[jl] = Σ_{r=rk}^{m-1} u[r]·A[r, p0+jl], jl in [0,width) ---
                    //     Reflector columns (jl<k, now holding u_i) give acc[jl] = uₖᵀuᵢ (the compact-WY
                    //     aux); trailing columns (jl>k, still original data) give F's direct term. One
                    //     unit-stride axpy per row — the read-only GEMV pass over the stale trailing
                    //     matrix that replaces the unblocked kernel's two memory-bound passes.
                    UnsafeUtility.MemClear(accp, (long)width * UnsafeUtility.SizeOf<double>());
                    for (int r = rk; r < m; r++)
                        UnsafeOP.axpy(accp, Ap + (long)r * n + p0, up[r], width);

                    // --- 6. new F column: F[jl,k] = acc[jl] − Σ_{i<k} F[jl,i]·acc[i]  (trailing jl only) ---
                    for (int jl = k + 1; jl < width; jl++)
                    {
                        double* Fjl = Fp + (long)jl * QRCP_BLOCK;
                        double s = accp[jl];
                        for (int i = 0; i < k; i++)
                            s -= Fjl[i] * accp[i];
                        Fjl[k] = s;
                    }

                    // --- 7. bring row rk of the trailing part up to date (becomes R; feeds the downdate) ---
                    //     A[rk, p0+jl] −= Σ_{i=0}^{k} u_i[rk]·F[jl,i]  — 0..k INCLUSIVE of the reflector
                    //     just generated (its contribution to this row arrives via F's new column).
                    {
                        double* Ark = Ap + (long)rk * n + p0;       // A[rk, p0 + i]
                        for (int jl = k + 1; jl < width; jl++)
                        {
                            double* Fjl = Fp + (long)jl * QRCP_BLOCK;
                            double s = (double)0;
                            for (int i = 0; i <= k; i++)
                                s += Ark[i] * Fjl[i];
                            Ark[jl] -= s;                            // Ark[jl] == A[rk, p0+jl]
                        }
                    }

                    // --- 8. downdate trailing norms (guarded). Trip ⇒ MARK (leave vn1 stale) + cut panel.
                    //     Unlike the unblocked core we must NOT re-sum on the spot: the trailing matrix
                    //     is stale below row rk mid-panel, so an immediate re-sum would be wrong. LAPACK
                    //     defers to panel end; we mark and, on the first trip, cut the panel short. ---
                    bool tripped = false;
                    {
                        double* Ark = Ap + (long)rk * n;
                        for (int jl = k + 1; jl < width; jl++)
                        {
                            int c = p0 + jl;
                            double v1 = vn1p[c];
                            if (v1 <= (double)0)
                                continue;

                            double v2 = vn2p[c];
                            if (v2 <= (double)0)
                            {
                                markp[c] = (double)1; tripped = true; continue;   // defensive; see unblocked core
                            }

                            double ratio = math.abs(Ark[c]) / v1;
                            double temp = math.max((double)0, ((double)1 + ratio) * ((double)1 - ratio));
                            double dse = v1 / v2;
                            double temp2 = temp * dse * dse;

                            if (temp2 <= Consts.doubleSqrtEps) { markp[c] = (double)1; tripped = true; }
                            else vn1p[c] = v1 * math.sqrt(temp);
                        }
                    }

                    if (tripped) { kb = k + 1; break; }
                }

                // --- panel flush: one rank-kb GEMM applies the whole panel's deferred trailing update.
                //     A[rows cStart.., cols cStart..) −= V·Fᵀ, with V = the kb stored reflectors and
                //     W := Fᵀ (kb x cw) built by transposing F's flush rows. Row rk_last is already
                //     current from step 7, so the flush starts one row below it (cStart = p0+kb). ---
                int cStart = p0 + kb;
                int cw = n - cStart;
                int frows = m - cStart;
                if (cw > 0 && frows > 0)
                {
                    double* Wp = Wbuf.Data.Ptr;
                    for (int i = 0; i < kb; i++)
                    {
                        double* Wi = Wp + (long)i * cw;
                        for (int jl2 = 0; jl2 < cw; jl2++)
                            Wi[jl2] = Fp[(long)(kb + jl2) * QRCP_BLOCK + i];   // Wᵀ: W[i,jl'] = F[kb+jl', i]
                    }
                    double* Vp = Ap + (long)cStart * n + p0;        // V: rows [cStart,m), cols [p0, p0+kb)
                    double* Cp = Ap + (long)cStart * n + cStart;    // C: rows [cStart,m), cols [cStart,n)
                    UnsafeOP.wySubVW(Vp, n, Cp, n, frows, kb, cw, Wp);
                }

                // --- re-sum marked columns over the now-updated trailing matrix (rows [cStart, m)) ---
                if (cw > 0)
                {
                    for (int c = cStart; c < n; c++)
                    {
                        if (markp[c] == (double)0)
                            continue;
                        double s = (double)0;
                        for (int r = cStart; r < m; r++)
                        {
                            double a = Ap[(long)r * n + c];
                            s += a * a;
                        }
                        double nrm = math.sqrt(s);
                        vn1p[c] = nrm;
                        vn2p[c] = nrm;
                        markp[c] = (double)0;
                    }
                }

                p0 += kb;                                  // advance by kb (not pb) so cut columns re-enter
            }

            // R off-diagonal from A's upper triangle (each R[d,d] was written per step above).
            for (int r = 0; r < R.M_Rows; r++)
            for (int c = 0; c < R.N_Cols; c++)
            {
                if (c < r) R[r, c] = 0;
                else if (c > r) R[r, c] = A_to_Q[r, c];
            }

            // Reconstruct Q from the stored reflectors via the shared blocked-WY kernel — decomp path
            // only. The fused solve already has Qᵀb in bp and leaves A_to_Q destroyed (no Q needed).
            if (!fusedSolve)
            {
                QR.reconstructQBlocked(ref A_to_Q, ref Vpanel, ref Tbuf, ref Wbuf, ref tcolBuf, ref VfullBuf);
                VfullBuf.Dispose();
                tcolBuf.Dispose();
                Tbuf.Dispose();
                Vpanel.Dispose();
            }

            Wbuf.Dispose();
            mark.Dispose();
            acc.Dispose();
            F.Dispose();

            return new DirectSolveInfo { status = DirectSolveStatus.Success };
        }

        // Allocating wrapper: allocates the scratch vector u (Allocator.Temp) and delegates.
        // The caller still owns P (its size carries the column count and it is reset internally).
        /// <remarks>R must not alias A_to_Q (unchecked) — see the 4-arg overload.</remarks>
        /// <param name="A_to_Q">On entry A; on exit the orthogonal factor Q.</param>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirectSolveInfo decompInPlace(ref doubleMxN A_to_Q, ref doubleMxN R, ref Pivot P)
        {
            var u = new doubleN(A_to_Q.M_Rows, Allocator.Temp, false);
            var info = decompInPlace(ref A_to_Q, ref R, ref P, ref u);
            u.Dispose();
            return info;
        }

        // ---- decomp: A-preserving variants (copy A into Q, then delegate to decompInPlace) ----

        /// <summary>
        /// Column-pivoted QR preserving A: A is copied into Q (one memcpy), then factored via
        /// decompInPlace. Q (caller-allocated, same dimensions as A) receives the orthogonal factor.
        /// Always reports DirectSolveStatus.Success — see decompInPlace.
        /// </summary>
        /// <remarks>R must not alias A_to_Q/Q (unchecked) — see decompInPlace. If R, P, or u is the
        /// wrong size, this throws AFTER Q has already been overwritten with a copy of A (still
        /// un-factored); A itself is always preserved.</remarks>
        /// <param name="Q">Output only; prior contents ignored; safe to allocate with uninit: true. Receives the orthogonal factor.</param>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirectSolveInfo decomp(in doubleMxN A, ref doubleMxN Q, ref doubleMxN R, ref Pivot P, ref doubleN u)
        {
            if (Q.M_Rows != A.M_Rows || Q.N_Cols != A.N_Cols)
                throw new ArgumentException("QRCP.decomp: Q must have the same dimensions as A");

            Q.CopyFrom(in A);
            return decompInPlace(ref Q, ref R, ref P, ref u);
        }

        /// <summary>
        /// decomp routed through caller-owned <see cref="doubleQRCPCache"/> scratch (vn1/vn2) — see
        /// decompInPlace's cache overload. A is copied into Q (one memcpy), then factored in place.
        /// </summary>
        /// <remarks>R must not alias A_to_Q/Q (unchecked) — see decompInPlace. If R, P, u, or the
        /// cache is mis-sized, this throws AFTER Q has already been overwritten with a copy of A
        /// (still un-factored); A itself is always preserved.</remarks>
        /// <param name="Q">Output only; prior contents ignored; safe to allocate with uninit: true. Receives the orthogonal factor.</param>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirectSolveInfo decomp(in doubleMxN A, ref doubleMxN Q, ref doubleMxN R, ref Pivot P, ref doubleN u, ref doubleQRCPCache cache)
        {
            if (Q.M_Rows != A.M_Rows || Q.N_Cols != A.N_Cols)
                throw new ArgumentException("QRCP.decomp: Q must have the same dimensions as A");

            Q.CopyFrom(in A);
            return decompInPlace(ref Q, ref R, ref P, ref u, ref cache);
        }

        /// <summary>
        /// decomp allocating its scratch vector u (Allocator.Temp). See the 5-arg overload for
        /// semantics.
        /// </summary>
        /// <remarks>R must not alias A_to_Q/Q (unchecked). If R or P is the wrong size, this throws
        /// AFTER Q has already been overwritten with a copy of A (still un-factored); A itself is
        /// always preserved.</remarks>
        /// <param name="Q">Output only; prior contents ignored; safe to allocate with uninit: true. Receives the orthogonal factor.</param>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirectSolveInfo decomp(in doubleMxN A, ref doubleMxN Q, ref doubleMxN R, ref Pivot P)
        {
            if (Q.M_Rows != A.M_Rows || Q.N_Cols != A.N_Cols)
                throw new ArgumentException("QRCP.decomp: Q must have the same dimensions as A");

            Q.CopyFrom(in A);
            return decompInPlace(ref Q, ref R, ref P);
        }

        /// <summary>
        /// QRCP-based rank-safe least-squares: basic (truncated) solution. Solves A x ≈ b (m >= n)
        /// for a possibly rank-deficient A using column-pivoted QR (Businger-Golub, A·P = Q·R) to
        /// expose the numerical rank r: the R diagonal is non-increasing, so r = count of leading
        /// entries with |R[i,i]| &gt; tol, where tol = relTol * |R[0,0]| and relTol defaults to
        /// max(m,n) * Consts.doubleZeroThreshold (matching SVD.pinvSolve / Analysis.rank). A
        /// negative relTol is an "auto" sentinel that selects that same default.
        ///
        /// Only the leading r×r block of R is back-substituted (divide-safe by construction: every
        /// used R diagonal exceeds tol); the remaining (n-r) free variables are set to zero in the
        /// permuted ordering, then P is un-applied to recover x. This is the BASIC (truncated)
        /// solution: it minimizes the residual ‖Ax - b‖ but is NOT the minimum-norm solution — use
        /// <see cref="minNormSolveInPlace(ref doubleMxN, ref doubleN, ref doubleN, ref doubleMxN, ref Pivot, ref doubleN, double)"/>
        /// (complete orthogonal decomposition, direct-factorization cost) or SVD.pinvSolve (iterative)
        /// for that. When A has full column rank (r == n) the result is identical to ordinary QR
        /// least-squares (and to minNormSolveInPlace, which then coincides with it).
        ///
        /// DESTRUCTIVE FAST PATH (mirrors QR.solveInPlace): factors A_to_Q's own buffer in place (no
        /// memcpy, no separate Q scratch) and applies Qᵀ to b as the reflectors are generated, so it
        /// never forms or reconstructs Q. On return A_to_Q is DESTROYED (stored reflectors + partial R, contents undefined) and b is
        /// DESTROYED (overwritten with Qᵀb). Need the orthogonal factor Q? Use QRCP.decompInPlace /
        /// QRCP.decomp instead, which reconstruct it.
        /// </summary>
        /// <param name="A_to_Q">On entry A (m x n, m >= n); DESTROYED on exit (NOT the orthogonal factor — use decompInPlace for Q).</param>
        /// <param name="b">Right-hand side, length m. DESTROYED (overwritten with Qᵀb). Must not alias x.</param>
        /// <param name="x">Output only; prior contents ignored; safe to allocate with uninit: true. Solution, length n.</param>
        /// <param name="R">Scratch: n x n (receives upper-triangular factor; consumed).</param>
        /// <param name="P">Scratch: column Pivot of size n (reset internally).</param>
        /// <param name="u">Scratch: length EXACTLY m (Householder workspace; first n entries are
        /// repurposed for the un-permute scatter after the decomposition).</param>
        /// <param name="relTol">Rank threshold ratio; tol = relTol * |R[0,0]|. Negative = auto default.</param>
        /// <returns>Status Success (r == n, full rank) or RankDeficient (r &lt; n, still a usable
        /// truncated least-squares solution); rank = detected r. See
        /// <see cref="RankInfo.Solved"/>.</returns>
        /// <remarks>R must not alias A_to_Q (unchecked) — see decompInPlace.</remarks>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                           ref doubleMxN R, ref Pivot P,
                                           ref doubleN u, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;

            if (m < n)
                throw new ArgumentException("QRCP.solveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("QRCP.solveInPlace: b.N must equal A_to_Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("QRCP.solveInPlace: x.N must equal A_to_Q.N_Cols");
            if (R.M_Rows != n || R.N_Cols != n)
                throw new ArgumentException("QRCP.solveInPlace: R must be N_Cols x N_Cols");
            if (P.N != n)
                throw new ArgumentException("QRCP.solveInPlace: P.N must equal A_to_Q.N_Cols");
            if (u.N != m)
                throw new ArgumentException("QRCP.solveInPlace: u.N must equal A_to_Q.M_Rows");

            // Negative relTol is an "auto" sentinel: use the library-standard rank threshold
            // (same default as SVD.pinvSolve / Analysis.rank). This also makes the threshold
            // divide-safe (tol >= 0), so a stray negative can never inflate rank into a divide-by-tiny.
            if (relTol < (double)0)
                relTol = (double)(math.max(m, n)) * Consts.doubleZeroThreshold;

            // Degenerate: zero-column system.
            if (n == 0) return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            // Fused destructive solve (A_to_Q and b BOTH destroyed): apply Qᵀ to b during the blocked
            // factorization and skip Q reconstruction — see solveInPlaceFusedDispatch. vn1/vn2 are the
            // norm-downdating scratch (Temp here; the cache overload supplies its own).
            var vn1 = new doubleN(n, Allocator.Temp, false);
            var vn2 = new doubleN(n, Allocator.Temp, false);
            var info = solveInPlaceFusedDispatch(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, ref vn1, ref vn2, relTol);
            vn2.Dispose();
            vn1.Dispose();
            return info;
        }

        /// <summary>
        /// solveInPlace routed through caller-owned <see cref="doubleQRCPCache"/> scratch (vn1/vn2)
        /// for the internal factorization — avoids the per-call Temp vn1/vn2 the 7-arg primitive
        /// allocates. Same DESTRUCTIVE fast-path semantics as the 7-arg primitive above (A_to_Q and b
        /// both destroyed; Q is never formed).
        /// </summary>
        /// <param name="A_to_Q">On entry A (m x n, m >= n); DESTROYED on exit (NOT the orthogonal factor — use decompInPlace for Q).</param>
        /// <param name="b">Right-hand side, length m. DESTROYED (overwritten with Qᵀb). Must not alias x.</param>
        /// <param name="x">Output only; prior contents ignored; safe to allocate with uninit: true. Solution, length n.</param>
        /// <param name="R">Scratch: n x n (receives upper-triangular factor; consumed).</param>
        /// <param name="P">Scratch: column Pivot of size n (reset internally).</param>
        /// <param name="u">Scratch: length EXACTLY m.</param>
        /// <param name="cache">Caller-owned vn1/vn2 scratch — see Arena.doubleQRCPCache.</param>
        /// <param name="relTol">Rank threshold ratio; tol = relTol * |R[0,0]|. Negative = auto default.</param>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                           ref doubleMxN R, ref Pivot P,
                                           ref doubleN u, ref doubleQRCPCache cache, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;

            if (m < n)
                throw new ArgumentException("QRCP.solveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("QRCP.solveInPlace: b.N must equal A_to_Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("QRCP.solveInPlace: x.N must equal A_to_Q.N_Cols");
            if (R.M_Rows != n || R.N_Cols != n)
                throw new ArgumentException("QRCP.solveInPlace: R must be N_Cols x N_Cols");
            if (P.N != n)
                throw new ArgumentException("QRCP.solveInPlace: P.N must equal A_to_Q.N_Cols");
            if (u.N != m)
                throw new ArgumentException("QRCP.solveInPlace: u.N must equal A_to_Q.M_Rows");

            if (relTol < (double)0)
                relTol = (double)(math.max(m, n)) * Consts.doubleZeroThreshold;

            if (n == 0) return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            RequireQRCPWorkspace(in cache, n);

            // Fused destructive solve through the caller's vn1/vn2 — see solveInPlaceFusedDispatch.
            return solveInPlaceFusedDispatch(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, ref cache.vn1, ref cache.vn2, relTol);
        }

        // Default-tolerance cache overload: passes the auto sentinel (relTol < 0) — see the 7-arg
        // primitive's default-tolerance overload below.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                           ref doubleMxN R, ref Pivot P,
                                           ref doubleN u, ref doubleQRCPCache cache)
        {
            return solveInPlace(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, ref cache, (double)(-1));
        }

        // Destructive fused-solve dispatch: the fast path for QRCP.solveInPlace. Once N_Cols is wide
        // enough to block (>= 2*QRCP_BLOCK), it applies Qᵀ to b DURING the blocked factorization and
        // skips Q reconstruction entirely (decompInPlaceBlockedCore's fusedSolve mode), then finishes
        // straight from Qᵀb. Below the gate it uses
        // the unblocked core (which forms Q cheaply at small n) plus the dot-based finish, unchanged.
        // BOTH A_to_Q and b are destroyed. Callers supply vn1/vn2 (cache) or Temp-allocate them.
        static unsafe RankInfo solveInPlaceFusedDispatch(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                                         ref doubleMxN R, ref Pivot P, ref doubleN u,
                                                         ref doubleN vn1, ref doubleN vn2, double relTol)
        {
            // See decompInPlaceBlockedCore for why this is a method-local const, not a class field.
            const int QRCP_BLOCK = 32;

            if (A_to_Q.N_Cols >= Consts.doubleQrcpBlockMinN)   // float/double split (see Consts); default 2*QRCP_BLOCK
                decompInPlaceBlockedCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, b.Data.Ptr, 1, null, true);
            else
                decompInPlaceCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, b.Data.Ptr, 1, null, true);

            // b now holds Qᵀb (both cores fused), consumed directly by the finish.
            return solveInPlaceFinish(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, relTol);
        }

        // Shared tail: rank detection from R's diagonal + back-substitution + un-permute. Factored
        // out so the plain-scratch and cache-scratch overloads above (which differ only in HOW the
        // decomposition step is reached) share one copy of this logic — see decompInPlaceCore for the
        // analogous split on the decomposition side.
        // Both solve cores (blocked + unblocked) run in fused mode, so on entry b ALREADY holds Qᵀb
        // (each reflector was applied to it during factorization) and A_to_Q is destroyed — NOT Q.
        // So c = leading n entries of b; no dot(b, Q). Rank, back-substitution and un-permute follow.
        static RankInfo solveInPlaceFinish(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                            ref doubleMxN R, ref Pivot P, ref doubleN u, double relTol)
        {
            int n = A_to_Q.N_Cols;

            // Step 2: determine numerical rank r from R's non-increasing diagonal.
            // tol = relTol * |R[0,0]|. When R[0,0] == 0 tol == 0, and |R[0,0]| > 0 is false
            // → rank stays 0. NaN in R[0,0] → tol = NaN → all comparisons false → rank = 0.
            double tol = relTol * math.abs(R[0, 0]);
            int rank = 0;
            for (int i = 0; i < n; i++)
            {
                if (math.abs(R[i, i]) > tol)
                    rank++;
                else
                    break;
            }

            // Step 3: zero matrix (rank == 0) → x = 0, done.
            if (rank == 0)
            {
                for (int j = 0; j < n; j++)
                    x[j] = (double)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            int r = rank;

            // Step 4: c = Qᵀb into x. b already holds Qᵀb (fused factorization), so c is just its
            // leading n entries — x[j] = (Qᵀb)[j] = b[j] for j in [0, n).
            for (int j = 0; j < n; j++)
                x[j] = b[j];

            // Step 5: back-solve the leading r×r block of R in place.
            // x holds c = Qᵀb; overwrite x[0..r-1] with the triangular solution.
            // Every R[i,i] for i < r satisfies |R[i,i]| > tol, so no divide-by-zero.
            for (int i = r - 1; i >= 0; i--)
            {
                double sum = (double)0;
                for (int j = i + 1; j < r; j++)
                    sum += R[i, j] * x[j];
                x[i] = (x[i] - sum) / R[i, i];
            }
            // Zero the free variables (columns beyond the numerical rank).
            for (int j = r; j < n; j++)
                x[j] = (double)0;

            // Step 6: un-permute — scatter from permuted ordering back to original column ordering.
            // QRCP gives A·P = Q·R where P[j] = original column index promoted to position j.
            // The permuted solution z (in x) satisfies: x_final[P[j]] = z[j].
            // Borrow u[0..n-1] as scatter scratch (u is no longer needed after Step 1).
            for (int j = 0; j < n; j++)
                u[j] = x[j];
            for (int j = 0; j < n; j++)
                x[P[j]] = u[j];

            return new RankInfo
            {
                status = (r < n) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        // Default-tolerance overload: passes the auto sentinel (relTol < 0), so the primitive
        // uses max(m,n) * Consts.doubleZeroThreshold (consistent with SVD.pinvSolve / Analysis.rank).
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                           ref doubleMxN R, ref Pivot P,
                                           ref doubleN u)
        {
            return solveInPlace(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, (double)(-1));
        }

        /// <summary>
        /// Allocating convenience wrapper: allocates R (n×n), P (n-Pivot) and u (m) from
        /// Allocator.Temp and delegates to the zero-alloc primitive. Use the primitive in hot loops
        /// to avoid repeated Temp allocs.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                           double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;

            // Replicate the primitive's own dimension checks (see the 7-arg overload above) BEFORE
            // allocating R/P/u, so a caller error can't leak the Temp allocations (thrown mid-call,
            // past the allocs but before the Dispose calls below).
            if (m < n)
                throw new ArgumentException("QRCP.solveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("QRCP.solveInPlace: b.N must equal A_to_Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("QRCP.solveInPlace: x.N must equal A_to_Q.N_Cols");

            var R = new doubleMxN(n, n, Allocator.Temp, false);
            var P = new Pivot(n, Allocator.Temp);
            var u = new doubleN(m, Allocator.Temp, false);
            var info = solveInPlace(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, relTol);
            u.Dispose();
            P.Dispose();
            R.Dispose();
            return info;
        }

        /// <summary>
        /// Allocating convenience wrapper with default tolerance (max(m,n) * Consts.doubleZeroThreshold,
        /// matching SVD.pinvSolve / Analysis.rank).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x)
        {
            return solveInPlace(ref A_to_Q, ref b, ref x, (double)(-1));
        }

        // ---- COD (complete orthogonal decomposition): MINIMUM-NORM rank-safe least squares ----
        //
        // solveInPlace above gives the BASIC (truncated) solution, which is NOT minimum-norm for a
        // rank-deficient A. minNormSolveInPlace closes that gap: it produces x = A⁺b (the pseudoinverse
        // / minimum-norm least-squares solution), the SAME answer SVD.pinvSolve gives, but at
        // direct-factorization cost (one QRCP + one small LQ on the top r×n block of R) instead of an
        // iterative SVD. This is LAPACK's xGELSY strategy.
        //
        // Reuses LQ's row-Householder kernels (genHouseholderRow / applyHouseholderRight /
        // applyQtFromReflectors) rather than a bespoke xTZRZF RZ-factorization — the same no-transpose
        // reuse LQRP is built on. The LQ compress is O(r²n), negligible against the O(mn²) QRCP.

        // Fused QRCP factor shared by every minNormSolveInPlace overload: run the (blocked or unblocked)
        // core in fusedSolve mode so b becomes Qᵀb, A_to_Q is destroyed (reflectors), R and P are filled;
        // Q is never reconstructed. vn1/vn2 are the norm-downdating scratch. Returns nothing (results are
        // in the ref args) — the rank read + COD/basic finish follow in the caller.
        static unsafe void minNormFactor(ref doubleMxN A_to_Q, ref doubleN b, ref doubleMxN R, ref Pivot P,
                                          ref doubleN u, ref doubleN vn1, ref doubleN vn2)
        {
            if (A_to_Q.N_Cols >= Consts.doubleQrcpBlockMinN)   // float/double split (see Consts); default 2*QRCP_BLOCK
                decompInPlaceBlockedCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, b.Data.Ptr, 1, null, true);
            else
                decompInPlaceCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, b.Data.Ptr, 1, null, true);
        }

        // COD completion for the rank-deficient (r < n) case (see the section header above). On entry:
        // b holds Qᵀb, R holds the upper-triangular factor, P the column pivot, r
        // the detected numerical rank (0 < r < n). Fills x with the minimum-norm least-squares solution
        // and returns RankDeficient (r < n is the only path that reaches here). Allocates one set of
        // Allocator.Temp COD scratch (M/L̃/reflector-vector/reduced-RHS); the LQ compress is O(r²n),
        // negligible against the QRCP that produced R.
        static unsafe RankInfo minNormCodFinish(ref doubleN b, ref doubleN x, ref doubleMxN R, ref Pivot P,
                                                ref doubleN u, int r)
        {
            int n = R.N_Cols;

            // M = [R11 R12] = R's top r rows (a contiguous r*n block of R's n×n row-major buffer). LQ
            // reduces it in place to L̃ (lower-tri) plus stored row-reflectors (Qz). L̃'s diagonal is
            // captured during the sweep; its sub-diagonal survives in M (the reflector store only
            // overwrites columns >= d of each row) — same layout LQ.lqKernel / LQRP.lqrpKernel use.
            var M   = new doubleMxN(r, n, Allocator.Temp, false);
            var Lc  = new doubleMxN(r, r, Allocator.Temp, false);
            var vrow = new doubleN(n, Allocator.Temp, false);
            var w   = new doubleN(n, Allocator.Temp, false);

            UnsafeUtility.MemCpy(M.Data.Ptr, R.Data.Ptr, (long)r * n * UnsafeUtility.SizeOf<double>());

            double zeroThreshold = Consts.doubleZeroThreshold * Norms.LInf(in M);
            for (int d = 0; d < r; d++)
            {
                LQ.genHouseholderRow(ref M, ref vrow, d, d, zeroThreshold);
                LQ.applyHouseholderRight(ref M, ref vrow, d, d);
                Lc[d, d] = M[d, d];                          // capture L̃ diagonal BEFORE the reflector overwrite
                for (int c = d; c < n; c++)
                    M[d, c] = vrow[c];                       // stash reflector v_d into M[d, d..n)
            }
            // L̃'s below-diagonal (survived in M) + zero the strict upper triangle.
            for (int i = 0; i < r; i++)
            {
                for (int c = 0; c < i; c++)     Lc[i, c] = M[i, c];
                for (int c = i + 1; c < r; c++) Lc[i, c] = (double)0;
            }

            // Forward-solve L̃ w = c1, c1 = (Qᵀb)[0..r) = b[0..r). M has full row rank r (R11 is r×r
            // full rank), so L̃ is invertible and every L̃[i,i] is nonzero (divide-safe by construction,
            // like the basic solve's R11 block).
            for (int i = 0; i < r; i++)
            {
                double sum = (double)0;
                for (int j = 0; j < i; j++)
                    sum += Lc[i, j] * w[j];
                w[i] = (b[i] - sum) / Lc[i, i];
            }
            for (int i = r; i < n; i++)
                w[i] = (double)0;                            // (applyQtFromReflectors only reads w[0..r), pad is cosmetic)

            // x = Qzᵀ w straight from M's stored reflectors (no dense Qz). x is in the PERMUTED column
            // ordering; un-permute below.
            LQ.applyQtFromReflectors(ref M, ref w, ref x);

            // Un-permute columns: x_final[P[j]] = x[j]. Borrow u[0..n) as scatter scratch (u is free
            // after the factorization), matching solveInPlaceFinish.
            for (int j = 0; j < n; j++) u[j] = x[j];
            for (int j = 0; j < n; j++) x[P[j]] = u[j];

            w.Dispose();
            vrow.Dispose();
            Lc.Dispose();
            M.Dispose();

            return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = r };
        }

        /// <summary>
        /// QRCP-based MINIMUM-NORM rank-safe least-squares (complete orthogonal decomposition / xGELSY).
        /// Solves A x ≈ b (m ≥ n) for a possibly rank-deficient A and returns the pseudoinverse solution
        /// x = A⁺b — the minimum-2-norm vector among all least-squares minimizers — which is the SAME
        /// result <see cref="SVD.pinvSolve(ref doubleMxN, in doubleN, ref doubleN, double, int)"/> gives,
        /// but at direct-factorization cost (one QRCP plus one LQ on the r×n rank-revealed block) rather
        /// than an iterative SVD. When A has full column rank (r == n) this coincides exactly with
        /// <see cref="solveInPlace(ref doubleMxN, ref doubleN, ref doubleN, ref doubleMxN, ref Pivot, ref doubleN, double)"/>
        /// (the basic solution is then already minimum-norm) — the difference appears only when r &lt; n.
        ///
        /// DESTRUCTIVE FAST PATH (like solveInPlace): factors A_to_Q's own buffer in place and applies
        /// Qᵀ to b during factorization, never forming Q. On return A_to_Q is DESTROYED (reflectors +
        /// partial R) and b is DESTROYED (overwritten with Qᵀb). Numerical rank r is read from R's
        /// non-increasing diagonal (tol = relTol·|R[0,0]|; negative relTol auto-selects
        /// max(m,n)·Consts.doubleZeroThreshold, matching SVD.pinvSolve / Analysis.rank).
        /// </summary>
        /// <param name="A_to_Q">On entry A (m x n, m ≥ n); DESTROYED on exit (reflectors, NOT Q).</param>
        /// <param name="b">Right-hand side, length m. DESTROYED (overwritten with Qᵀb). Must not alias x.</param>
        /// <param name="x">Output only; prior contents ignored; safe to allocate with uninit: true. Minimum-norm solution, length n.</param>
        /// <param name="R">Scratch: n x n (receives the upper-triangular factor; consumed).</param>
        /// <param name="P">Scratch: column Pivot of size n (reset internally).</param>
        /// <param name="u">Scratch: length EXACTLY m (Householder + un-permute scatter).</param>
        /// <param name="relTol">Rank threshold ratio; tol = relTol·|R[0,0]|. Negative = auto default.</param>
        /// <returns>Status Success (r == n) or RankDeficient (r &lt; n, still a usable minimum-norm
        /// solution); rank = detected r. See <see cref="RankInfo.Solved"/>.</returns>
        /// <remarks>R must not alias A_to_Q (unchecked) — see decompInPlace.</remarks>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                                   ref doubleMxN R, ref Pivot P, ref doubleN u, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;

            if (m < n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("QRCP.minNormSolveInPlace: b.N must equal A_to_Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: x.N must equal A_to_Q.N_Cols");
            if (R.M_Rows != n || R.N_Cols != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: R must be N_Cols x N_Cols");
            if (P.N != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: P.N must equal A_to_Q.N_Cols");
            if (u.N != m)
                throw new ArgumentException("QRCP.minNormSolveInPlace: u.N must equal A_to_Q.M_Rows");

            if (relTol < (double)0)
                relTol = (double)(math.max(m, n)) * Consts.doubleZeroThreshold;

            if (n == 0) return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            // Fused QRCP factor: b ← Qᵀb, A destroyed, R/P filled (vn1/vn2 = downdating scratch).
            unsafe
            {
                var vn1 = new doubleN(n, Allocator.Temp, false);
                var vn2 = new doubleN(n, Allocator.Temp, false);
                minNormFactor(ref A_to_Q, ref b, ref R, ref P, ref u, ref vn1, ref vn2);
                vn2.Dispose();
                vn1.Dispose();
            }

            // Numerical rank r from R's non-increasing diagonal (see solveInPlaceFinish for the NaN/zero
            // edge behaviour — identical here).
            double tol = relTol * math.abs(R[0, 0]);
            int r = 0;
            for (int i = 0; i < n; i++)
            {
                if (math.abs(R[i, i]) > tol) r++;
                else break;
            }

            if (r == 0)
            {
                for (int j = 0; j < n; j++) x[j] = (double)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            // r == n: full column rank ⇒ the basic solution IS minimum-norm. Reuse the basic tail
            // (b already holds Qᵀb) — no COD needed.
            if (r == n)
                return solveInPlaceFinish(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, relTol);

            // r < n: complete the orthogonal decomposition and produce the minimum-norm solution.
            unsafe { return minNormCodFinish(ref b, ref x, ref R, ref P, ref u, r); }
        }

        /// <summary>minNormSolveInPlace with the default rank tolerance (max(m,n)·Consts.doubleZeroThreshold,
        /// matching SVD.pinvSolve / Analysis.rank). See the primitive for full semantics.</summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x,
                                                   ref doubleMxN R, ref Pivot P, ref doubleN u)
        {
            return minNormSolveInPlace(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, (double)(-1));
        }

        /// <summary>
        /// Allocating convenience wrapper: allocates R (n×n), P (n-Pivot) and u (m) from Allocator.Temp
        /// and delegates to the zero-alloc primitive. DESTROYS A_to_Q and b (see the primitive). Use the
        /// primitive in hot loops to avoid repeated Temp allocs.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;

            // Replicate the primitive's dimension checks BEFORE allocating (validate-before-alloc).
            if (m < n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (b.N != m)
                throw new ArgumentException("QRCP.minNormSolveInPlace: b.N must equal A_to_Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: x.N must equal A_to_Q.N_Cols");

            var R = new doubleMxN(n, n, Allocator.Temp, false);
            var P = new Pivot(n, Allocator.Temp);
            var u = new doubleN(m, Allocator.Temp, false);
            var info = minNormSolveInPlace(ref A_to_Q, ref b, ref x, ref R, ref P, ref u, relTol);
            u.Dispose();
            P.Dispose();
            R.Dispose();
            return info;
        }

        /// <summary>Allocating convenience wrapper with default tolerance (max(m,n)·Consts.doubleZeroThreshold).
        /// DESTROYS A_to_Q and b.</summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleN b, ref doubleN x)
        {
            return minNormSolveInPlace(ref A_to_Q, ref b, ref x, (double)(-1));
        }

        // ---- multi-RHS forms: rank-safe least squares for a whole matrix of right-hand sides ----
        //
        // Two entry points, mirroring the single-RHS pair:
        //   decompSolve(Q, R, P, B, X)  — from a precomputed factorization; B PRESERVED, QᵀB is one
        //                                 GEMM, then a truncated block back-solve. Reuse across blocks.
        //   solveInPlace(A, B, X)       — FUSED and DESTRUCTIVE, exactly like the vector solveInPlace:
        //                                 Qᵀ is applied to B's columns as reflectors are generated and
        //                                 Q is NEVER reconstructed. A_to_Q and
        //                                 B are DESTROYED (A_to_Q -> reflectors + partial R, B -> QᵀB).

        // Shared tail: X's first n rows hold QᵀB (in the permuted column basis). Detect rank from R's
        // non-increasing diagonal, back-solve the leading r×r block for all k columns, zero the free
        // variables, and un-permute the rows. relTol must already be resolved (>= 0). See the vector
        // solveInPlaceFinish for the single-column derivation.
        static unsafe RankInfo finishFromQtB(ref doubleMxN X, ref doubleMxN R, in Pivot P, double relTol, int n, int k)
        {
            double tol = relTol * math.abs(R[0, 0]);
            int rank = 0;
            for (int i = 0; i < n; i++)
            {
                if (math.abs(R[i, i]) > tol) rank++;
                else break;
            }

            double* Xp = X.Data.Ptr;

            if (rank == 0)
            {
                for (long e = 0; e < (long)n * k; e++) Xp[e] = (double)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            int r = rank;

            // Back-solve the leading r×r block of R for all k columns (axpy across the k RHS). Every
            // used R[i,i] exceeds tol, so the divide is safe.
            for (int i = r - 1; i >= 0; i--)
            {
                double* Xi = Xp + (long)i * k;
                for (int j = i + 1; j < r; j++)
                    UnsafeOP.axpy(Xi, Xp + (long)j * k, -R[i, j], k);
                double inv = (double)1 / R[i, i];
                for (int c = 0; c < k; c++) Xi[c] *= inv;
            }
            // Zero the free variables (rows r..n-1 in the permuted ordering).
            for (int i = r; i < n; i++)
            {
                double* Xi = Xp + (long)i * k;
                for (int c = 0; c < k; c++) Xi[c] = (double)0;
            }

            // Un-permute rows: x_final[P[j], :] = z[j, :]. Scatter through a Temp copy of z (X's rows).
            var Z = new doubleMxN(n, k, Allocator.Temp, false);
            Z.CopyFrom(in X);
            double* Zp = Z.Data.Ptr;
            for (int j = 0; j < n; j++)
            {
                double* dst = Xp + (long)P[j] * k;
                double* src = Zp + (long)j * k;
                for (int c = 0; c < k; c++) dst[c] = src[c];
            }
            Z.Dispose();

            return new RankInfo
            {
                status = (r < n) ? DirectSolveStatus.RankDeficient : DirectSolveStatus.Success,
                rank = r
            };
        }

        /// <summary>
        /// QRCP rank-safe least-squares for a whole block of right-hand sides, from a precomputed
        /// column-pivoted factorization (A·P = Q·R, from QRCP.decompInPlace/decomp). Each RHS is a
        /// COLUMN of B (m x k, preserved); X (n x k) receives the *basic* (truncated) solution, must be
        /// distinct from B. Numerical rank r is read from R's non-increasing diagonal
        /// (tol = relTol·|R[0,0]|; relTol &lt; 0 auto-selects max(m,n)·Consts.doubleZeroThreshold). Only
        /// the leading r×r block of R is back-substituted; free variables are zeroed and P un-applied.
        /// Returns <see cref="RankInfo"/> (Success if r == n, else RankDeficient).
        /// </summary>
        /// <param name="Q">Orthogonal factor (m x n) from decompInPlace.</param>
        /// <param name="R">Upper-triangular factor (n x n) from decompInPlace.</param>
        /// <param name="P">Column pivot from decompInPlace.</param>
        /// <param name="B">Right-hand sides (m x k). Preserved. Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Solution (n x k).</param>
        public static RankInfo decompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                           ref doubleMxN B, ref doubleMxN X, double relTol)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;
            int k = B.N_Cols;

            if (X.M_Rows != n)
                throw new ArgumentException("QRCP.decompSolve: X.M_Rows must equal Q.N_Cols");
            if (B.M_Rows != m)
                throw new ArgumentException("QRCP.decompSolve: B.M_Rows must equal Q.M_Rows");
            if (X.N_Cols != k)
                throw new ArgumentException("QRCP.decompSolve: X.N_Cols must equal B.N_Cols");
            if (R.M_Rows != n || R.N_Cols != n)
                throw new ArgumentException("QRCP.decompSolve: R must be N_Cols x N_Cols");
            if (P.N != n)
                throw new ArgumentException("QRCP.decompSolve: P.N must equal Q.N_Cols");

            if (relTol < (double)0)
                relTol = (double)(math.max(m, n)) * Consts.doubleZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            // X = QᵀB (level-3 GEMM; ref-dest dot guards X-aliases-input and zeroes X first).
            Blas.dot(in Q, in B, ref X, transposeA: true);
            return finishFromQtB(ref X, ref R, in P, relTol, n, k);
        }

        /// <summary>Multi-RHS basic decompSolve with the default rank tolerance
        /// (max(m,n)·Consts.doubleZeroThreshold). See the primitive.</summary>
        public static RankInfo decompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                           ref doubleMxN B, ref doubleMxN X)
        {
            return decompSolve(ref Q, ref R, in P, ref B, ref X, (double)(-1));
        }

        /// <summary>
        /// QRCP rank-safe BASIC (truncated) least-squares from a precomputed factorization (A·P = Q·R),
        /// single right-hand side — the vector form of
        /// <see cref="decompSolve(ref doubleMxN, ref doubleMxN, in Pivot, ref doubleMxN, ref doubleMxN, double)"/>.
        /// Reuse one factorization to solve for many b. b (length m) is preserved; x (length n) receives
        /// the basic solution (already minimum-norm only at full column rank — for a rank-deficient
        /// minimum-norm solution use
        /// <see cref="minNormDecompSolve(ref doubleMxN, ref doubleMxN, in Pivot, ref doubleN, ref doubleN, double)"/>).
        /// Wraps b/x as single-column blocks and delegates to the multi-RHS solve (one small Temp pair).
        /// </summary>
        /// <param name="Q">Orthogonal factor (m x n) from decompInPlace/decomp.</param>
        /// <param name="R">Upper-triangular factor (n x n) from decompInPlace/decomp.</param>
        /// <param name="P">Column pivot from decompInPlace/decomp.</param>
        /// <param name="b">Right-hand side (length m). Preserved (read-only). Must not alias x.</param>
        /// <param name="x">Output only; prior contents ignored. Solution (length n).</param>
        public static RankInfo decompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                           ref doubleN b, ref doubleN x, double relTol)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;

            if (b.N != m)
                throw new ArgumentException("QRCP.decompSolve: b.N must equal Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("QRCP.decompSolve: x.N must equal Q.N_Cols");

            var B = new doubleMxN(m, 1, Allocator.Temp, true);
            var X = new doubleMxN(n, 1, Allocator.Temp, true);
            for (int i = 0; i < m; i++) B[i, 0] = b[i];
            var info = decompSolve(ref Q, ref R, in P, ref B, ref X, relTol);
            for (int j = 0; j < n; j++) x[j] = X[j, 0];
            X.Dispose();
            B.Dispose();
            return info;
        }

        /// <summary>Single-RHS basic decompSolve (factor-reuse) with the default rank tolerance. See the primitive.</summary>
        public static RankInfo decompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                           ref doubleN b, ref doubleN x)
        {
            return decompSolve(ref Q, ref R, in P, ref b, ref x, (double)(-1));
        }

        /// <summary>
        /// Factor-and-solve (multi-RHS), FUSED and DESTRUCTIVE — the fast path, mirroring the vector
        /// solveInPlace: column-pivoted QR of A_to_Q in place, applying Qᵀ to every column of B as the
        /// reflectors are generated, and NEVER reconstructing Q. On return
        /// A_to_Q is DESTROYED (reflectors + partial R, NOT the orthogonal factor — use decompInPlace
        /// for Q) and B is DESTROYED (overwritten with QᵀB). Returns <see cref="RankInfo"/>.
        /// </summary>
        /// <param name="A_to_Q">On entry A (m x n, m >= n); DESTROYED on exit.</param>
        /// <param name="B">Right-hand sides (m x k). DESTROYED (overwritten with QᵀB). Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Solution (n x k).</param>
        /// <param name="R">Scratch: n x n (receives R).</param>
        /// <param name="P">Scratch: column Pivot of size n (reset internally).</param>
        /// <param name="u">Scratch: length EXACTLY m.</param>
        public static unsafe RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X,
                                                   ref doubleMxN R, ref Pivot P, ref doubleN u, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;
            int k = B.N_Cols;

            if (m < n)
                throw new ArgumentException("QRCP.solveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("QRCP.solveInPlace: B.M_Rows must equal A_to_Q.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("QRCP.solveInPlace: X.M_Rows must equal A_to_Q.N_Cols");
            if (X.N_Cols != k)
                throw new ArgumentException("QRCP.solveInPlace: X.N_Cols must equal B.N_Cols");
            if (R.M_Rows != n || R.N_Cols != n)
                throw new ArgumentException("QRCP.solveInPlace: R must be N_Cols x N_Cols");
            if (P.N != n)
                throw new ArgumentException("QRCP.solveInPlace: P.N must equal A_to_Q.N_Cols");
            if (u.N != m)
                throw new ArgumentException("QRCP.solveInPlace: u.N must equal A_to_Q.M_Rows");

            if (relTol < (double)0)
                relTol = (double)(math.max(m, n)) * Consts.doubleZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            // Fused destructive solve: apply Qᵀ to B during the (blocked or unblocked) factorization
            // and skip Q reconstruction. vn1/vn2 are the norm-downdating scratch; acc is the length-k
            // reflector-apply accumulator for the multi-RHS fused path.
            var vn1 = new doubleN(n, Allocator.Temp, false);
            var vn2 = new doubleN(n, Allocator.Temp, false);
            var acc = new doubleN(k, Allocator.Temp, false);
            double* bp = B.Data.Ptr;
            double* accp = acc.Data.Ptr;

            if (n >= Consts.doubleQrcpBlockMinN)   // float/double split (see Consts); default 2*QRCP_BLOCK
                decompInPlaceBlockedCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, bp, k, accp, true);
            else
                decompInPlaceCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, bp, k, accp, true);

            // B now holds QᵀB (m x k). Copy its leading n rows into X, then finish (rank + back-solve
            // + un-permute) — same tail as decompSolve, just sourcing QᵀB from B instead of a GEMM.
            double* Xp = X.Data.Ptr;
            for (int i = 0; i < n; i++)
            {
                double* dst = Xp + (long)i * k;
                double* src = bp + (long)i * k;
                for (int c = 0; c < k; c++) dst[c] = src[c];
            }

            var info = finishFromQtB(ref X, ref R, in P, relTol, n, k);

            acc.Dispose();
            vn2.Dispose();
            vn1.Dispose();
            return info;
        }

        /// <summary>Multi-RHS solveInPlace (scratch) with the default rank tolerance. See the primitive.</summary>
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X,
                                            ref doubleMxN R, ref Pivot P, ref doubleN u)
        {
            return solveInPlace(ref A_to_Q, ref B, ref X, ref R, ref P, ref u, (double)(-1));
        }

        /// <summary>Allocating multi-RHS convenience: allocates R (n×n), P (n) and u (m) from
        /// Allocator.Temp. DESTROYS A_to_Q and B (see the scratch overload). Use that overload in hot loops.</summary>
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;

            if (m < n)
                throw new ArgumentException("QRCP.solveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("QRCP.solveInPlace: B.M_Rows must equal A_to_Q.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("QRCP.solveInPlace: X.M_Rows must equal A_to_Q.N_Cols");
            if (X.N_Cols != B.N_Cols)
                throw new ArgumentException("QRCP.solveInPlace: X.N_Cols must equal B.N_Cols");

            var R = new doubleMxN(n, n, Allocator.Temp, false);
            var P = new Pivot(n, Allocator.Temp);
            var u = new doubleN(m, Allocator.Temp, false);
            var info = solveInPlace(ref A_to_Q, ref B, ref X, ref R, ref P, ref u, relTol);
            u.Dispose();
            P.Dispose();
            R.Dispose();
            return info;
        }

        /// <summary>Allocating multi-RHS convenience with default tolerance. DESTROYS A_to_Q and B.</summary>
        public static RankInfo solveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X)
        {
            return solveInPlace(ref A_to_Q, ref B, ref X, (double)(-1));
        }

        // ---- multi-RHS COD: MINIMUM-NORM least squares for a whole block of right-hand sides ----
        //
        // The block form of minNormSolveInPlace / the single-RHS COD (see that section): x = A⁺B, the
        // minimum-norm least-squares solution for each column of B at once. Two entry points mirroring
        // the basic multi-RHS pair:
        //   minNormDecompSolve(Q,R,P,B,X) — from a precomputed factorization; B PRESERVED (QᵀB is one
        //                                   GEMM), then the block COD finish. Reuse across blocks.
        //   minNormSolveInPlace(A,B,X)    — FUSED and DESTRUCTIVE: Qᵀ applied to B's columns during
        //                                   factorization, Q never reconstructed. A_to_Q and B DESTROYED.

        // Shared block COD finish. On entry X's leading n rows hold QᵀB (in the pivoted column basis).
        // Detect rank r from R's diagonal; if r == n the basic block finish IS min-norm (reuse
        // finishFromQtB); else complete the orthogonal decomposition on the r×n block M = [R11 R12] (LQ
        // compress → L̃ + Qz reflectors), block-solve L̃ W1 = C1 (C1 = top r rows of QᵀB), form the
        // min-norm block Y = Qzᵀ[W1;0], and un-permute the rows into X. relTol must already be resolved
        // (>= 0). Allocates one set of Allocator.Temp COD scratch; the LQ compress is O(r²n).
        static unsafe RankInfo minNormFinishFromQtB(ref doubleMxN X, ref doubleMxN R, in Pivot P, double relTol, int n, int k)
        {
            double tol = relTol * math.abs(R[0, 0]);
            int rank = 0;
            for (int i = 0; i < n; i++)
            {
                if (math.abs(R[i, i]) > tol) rank++;
                else break;
            }

            if (rank == 0)
            {
                double* Xz = X.Data.Ptr;
                for (long e = 0; e < (long)n * k; e++) Xz[e] = (double)0;
                return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = 0 };
            }

            // r == n: full column rank, the basic block finish is already min-norm (no COD).
            if (rank == n)
                return finishFromQtB(ref X, ref R, in P, relTol, n, k);

            int r = rank;

            // LQ-compress M = R's top r×n block (contiguous r*n) → L̃ + Qz reflectors (see the single-RHS
            // minNormCodFinish for the layout).
            var M   = new doubleMxN(r, n, Allocator.Temp, false);
            var Lc  = new doubleMxN(r, r, Allocator.Temp, false);
            var vrow = new doubleN(n, Allocator.Temp, false);
            UnsafeUtility.MemCpy(M.Data.Ptr, R.Data.Ptr, (long)r * n * UnsafeUtility.SizeOf<double>());
            double zeroThreshold = Consts.doubleZeroThreshold * Norms.LInf(in M);
            for (int d = 0; d < r; d++)
            {
                LQ.genHouseholderRow(ref M, ref vrow, d, d, zeroThreshold);
                LQ.applyHouseholderRight(ref M, ref vrow, d, d);
                Lc[d, d] = M[d, d];
                for (int c = d; c < n; c++) M[d, c] = vrow[c];
            }
            for (int i = 0; i < r; i++)
            {
                for (int c = 0; c < i; c++)     Lc[i, c] = M[i, c];
                for (int c = i + 1; c < r; c++) Lc[i, c] = (double)0;
            }

            // W1 = L̃⁻¹ C1 (block forward-substitution; C1 = top r rows of QᵀB, held in X's first r rows).
            double* Xp = X.Data.Ptr;
            var W1 = new doubleMxN(r, k, Allocator.Temp, false);
            double* W1p = W1.Data.Ptr;
            for (int i = 0; i < r; i++)
            {
                double* Wi = W1p + (long)i * k;
                double* Xi = Xp + (long)i * k;               // C1 row i
                for (int c = 0; c < k; c++) Wi[c] = Xi[c];
                for (int j = 0; j < i; j++)
                    UnsafeOP.axpy(Wi, W1p + (long)j * k, -Lc[i, j], k);
                double inv = (double)1 / Lc[i, i];
                for (int c = 0; c < k; c++) Wi[c] *= inv;
            }

            // Y = Qzᵀ W1 (n×k) straight from M's reflectors, then un-permute rows into X: X[P[j],:] = Y[j,:].
            var Y = new doubleMxN(n, k, Allocator.Temp, false);
            LQ.applyQtFromReflectors(ref M, ref W1, ref Y);
            double* Yp = Y.Data.Ptr;
            for (int j = 0; j < n; j++)
            {
                double* dst = Xp + (long)P[j] * k;
                double* src = Yp + (long)j * k;
                for (int c = 0; c < k; c++) dst[c] = src[c];
            }

            Y.Dispose();
            W1.Dispose();
            vrow.Dispose();
            Lc.Dispose();
            M.Dispose();

            return new RankInfo { status = DirectSolveStatus.RankDeficient, rank = r };
        }

        /// <summary>
        /// QRCP MINIMUM-NORM (pseudoinverse) least-squares for a whole block of right-hand sides, from a
        /// precomputed column-pivoted factorization (A·P = Q·R). Each RHS is a COLUMN of B (m x k,
        /// preserved); X (n x k) receives x = A⁺B (must be distinct from B). This is the multi-RHS
        /// factor-reuse form of <see cref="minNormSolveInPlace(ref doubleMxN, ref doubleN, ref doubleN, ref doubleMxN, ref Pivot, ref doubleN, double)"/>:
        /// QᵀB is a single GEMM, then a block complete-orthogonal-decomposition finish. Setting B = I
        /// yields the pseudoinverse A⁺ itself. Returns <see cref="RankInfo"/>.
        /// </summary>
        /// <param name="Q">Orthogonal factor (m x n) from decompInPlace.</param>
        /// <param name="R">Upper-triangular factor (n x n) from decompInPlace.</param>
        /// <param name="P">Column pivot from decompInPlace.</param>
        /// <param name="B">Right-hand sides (m x k). Preserved. Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Minimum-norm solution (n x k).</param>
        public static unsafe RankInfo minNormDecompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                                         ref doubleMxN B, ref doubleMxN X, double relTol)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;
            int k = B.N_Cols;

            if (X.M_Rows != n)
                throw new ArgumentException("QRCP.minNormDecompSolve: X.M_Rows must equal Q.N_Cols");
            if (B.M_Rows != m)
                throw new ArgumentException("QRCP.minNormDecompSolve: B.M_Rows must equal Q.M_Rows");
            if (X.N_Cols != k)
                throw new ArgumentException("QRCP.minNormDecompSolve: X.N_Cols must equal B.N_Cols");
            if (R.M_Rows != n || R.N_Cols != n)
                throw new ArgumentException("QRCP.minNormDecompSolve: R must be N_Cols x N_Cols");
            if (P.N != n)
                throw new ArgumentException("QRCP.minNormDecompSolve: P.N must equal Q.N_Cols");

            if (relTol < (double)0)
                relTol = (double)(math.max(m, n)) * Consts.doubleZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            // X = QᵀB (level-3 GEMM; ref-dest dot guards X-aliases-input and zeroes X first), then the
            // shared block COD finish (rank-detect + compress + block solve + un-permute).
            Blas.dot(in Q, in B, ref X, transposeA: true);
            return minNormFinishFromQtB(ref X, ref R, in P, relTol, n, k);
        }

        /// <summary>minNormDecompSolve with the default rank tolerance. See the primitive for semantics.</summary>
        public static RankInfo minNormDecompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                                  ref doubleMxN B, ref doubleMxN X)
        {
            return minNormDecompSolve(ref Q, ref R, in P, ref B, ref X, (double)(-1));
        }

        /// <summary>
        /// QRCP MINIMUM-NORM (pseudoinverse) least-squares from a precomputed factorization (A·P = Q·R),
        /// single right-hand side — the vector form of
        /// <see cref="minNormDecompSolve(ref doubleMxN, ref doubleMxN, in Pivot, ref doubleMxN, ref doubleMxN, double)"/>.
        /// Reuse one factorization to solve for many b; returns x = A⁺b (the SAME answer SVD.pinvSolve
        /// gives). b (length m) is preserved; x (length n) receives the minimum-norm solution. Wraps b/x
        /// as single-column blocks and delegates to the multi-RHS COD solve (one small Temp pair).
        /// </summary>
        /// <param name="Q">Orthogonal factor (m x n) from decompInPlace/decomp.</param>
        /// <param name="R">Upper-triangular factor (n x n) from decompInPlace/decomp.</param>
        /// <param name="P">Column pivot from decompInPlace/decomp.</param>
        /// <param name="b">Right-hand side (length m). Preserved (read-only). Must not alias x.</param>
        /// <param name="x">Output only; prior contents ignored. Minimum-norm solution (length n).</param>
        public static RankInfo minNormDecompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                                  ref doubleN b, ref doubleN x, double relTol)
        {
            int m = Q.M_Rows;
            int n = Q.N_Cols;

            if (b.N != m)
                throw new ArgumentException("QRCP.minNormDecompSolve: b.N must equal Q.M_Rows");
            if (x.N != n)
                throw new ArgumentException("QRCP.minNormDecompSolve: x.N must equal Q.N_Cols");

            var B = new doubleMxN(m, 1, Allocator.Temp, true);
            var X = new doubleMxN(n, 1, Allocator.Temp, true);
            for (int i = 0; i < m; i++) B[i, 0] = b[i];
            var info = minNormDecompSolve(ref Q, ref R, in P, ref B, ref X, relTol);
            for (int j = 0; j < n; j++) x[j] = X[j, 0];
            X.Dispose();
            B.Dispose();
            return info;
        }

        /// <summary>Single-RHS min-norm decompSolve (factor-reuse) with the default rank tolerance. See the primitive.</summary>
        public static RankInfo minNormDecompSolve(ref doubleMxN Q, ref doubleMxN R, in Pivot P,
                                                  ref doubleN b, ref doubleN x)
        {
            return minNormDecompSolve(ref Q, ref R, in P, ref b, ref x, (double)(-1));
        }

        /// <summary>
        /// QRCP MINIMUM-NORM least-squares for a whole block of right-hand sides, FUSED and DESTRUCTIVE —
        /// the block form of the single-RHS <see cref="minNormSolveInPlace(ref doubleMxN, ref doubleN, ref doubleN, ref doubleMxN, ref Pivot, ref doubleN, double)"/>:
        /// column-pivoted QR of A_to_Q in place, Qᵀ applied to every column of B as reflectors are
        /// generated, Q never reconstructed, then a block complete-orthogonal-decomposition finish. On
        /// return A_to_Q is DESTROYED (reflectors + partial R) and B is DESTROYED (overwritten with QᵀB).
        /// X (n x k) receives x = A⁺B. Returns <see cref="RankInfo"/>.
        /// </summary>
        /// <param name="A_to_Q">On entry A (m x n, m >= n); DESTROYED on exit.</param>
        /// <param name="B">Right-hand sides (m x k). DESTROYED (overwritten with QᵀB). Must not alias X.</param>
        /// <param name="X">Output only; prior contents ignored. Minimum-norm solution (n x k).</param>
        /// <param name="R">Scratch: n x n (receives R).</param>
        /// <param name="P">Scratch: column Pivot of size n (reset internally).</param>
        /// <param name="u">Scratch: length EXACTLY m.</param>
        public static unsafe RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X,
                                                          ref doubleMxN R, ref Pivot P, ref doubleN u, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;
            int k = B.N_Cols;

            if (m < n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("QRCP.minNormSolveInPlace: B.M_Rows must equal A_to_Q.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: X.M_Rows must equal A_to_Q.N_Cols");
            if (X.N_Cols != k)
                throw new ArgumentException("QRCP.minNormSolveInPlace: X.N_Cols must equal B.N_Cols");
            if (R.M_Rows != n || R.N_Cols != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: R must be N_Cols x N_Cols");
            if (P.N != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: P.N must equal A_to_Q.N_Cols");
            if (u.N != m)
                throw new ArgumentException("QRCP.minNormSolveInPlace: u.N must equal A_to_Q.M_Rows");

            if (relTol < (double)0)
                relTol = (double)(math.max(m, n)) * Consts.doubleZeroThreshold;

            if (n == 0)
                return new RankInfo { status = DirectSolveStatus.Success, rank = 0 };

            // Fused factor: apply Qᵀ to B's columns during the (blocked or unblocked) factorization.
            var vn1 = new doubleN(n, Allocator.Temp, false);
            var vn2 = new doubleN(n, Allocator.Temp, false);
            var acc = new doubleN(k, Allocator.Temp, false);
            double* bp = B.Data.Ptr;
            double* accp = acc.Data.Ptr;

            if (n >= Consts.doubleQrcpBlockMinN)   // float/double split (see Consts); default 2*QRCP_BLOCK
                decompInPlaceBlockedCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, bp, k, accp, true);
            else
                decompInPlaceCore(ref A_to_Q, ref R, ref P, ref u, ref vn1, ref vn2, bp, k, accp, true);

            // B now holds QᵀB (m x k). Copy its leading n rows into X, then the shared block COD finish.
            double* Xp = X.Data.Ptr;
            for (int i = 0; i < n; i++)
            {
                double* dst = Xp + (long)i * k;
                double* src = bp + (long)i * k;
                for (int c = 0; c < k; c++) dst[c] = src[c];
            }

            var info = minNormFinishFromQtB(ref X, ref R, in P, relTol, n, k);

            acc.Dispose();
            vn2.Dispose();
            vn1.Dispose();
            return info;
        }

        /// <summary>minNormSolveInPlace (multi-RHS) with the default rank tolerance. See the primitive.</summary>
        public static RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X,
                                                   ref doubleMxN R, ref Pivot P, ref doubleN u)
        {
            return minNormSolveInPlace(ref A_to_Q, ref B, ref X, ref R, ref P, ref u, (double)(-1));
        }

        /// <summary>Allocating multi-RHS min-norm convenience: allocates R (n×n), P (n) and u (m) from
        /// Allocator.Temp. DESTROYS A_to_Q and B. Use the scratch overload in hot loops.</summary>
        public static RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X, double relTol)
        {
            int m = A_to_Q.M_Rows;
            int n = A_to_Q.N_Cols;

            if (m < n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: A_to_Q must be square or tall (M_Rows >= N_Cols)");
            if (B.M_Rows != m)
                throw new ArgumentException("QRCP.minNormSolveInPlace: B.M_Rows must equal A_to_Q.M_Rows");
            if (X.M_Rows != n)
                throw new ArgumentException("QRCP.minNormSolveInPlace: X.M_Rows must equal A_to_Q.N_Cols");
            if (X.N_Cols != B.N_Cols)
                throw new ArgumentException("QRCP.minNormSolveInPlace: X.N_Cols must equal B.N_Cols");

            var R = new doubleMxN(n, n, Allocator.Temp, false);
            var P = new Pivot(n, Allocator.Temp);
            var u = new doubleN(m, Allocator.Temp, false);
            var info = minNormSolveInPlace(ref A_to_Q, ref B, ref X, ref R, ref P, ref u, relTol);
            u.Dispose();
            P.Dispose();
            R.Dispose();
            return info;
        }

        /// <summary>Allocating multi-RHS min-norm convenience with default tolerance. DESTROYS A_to_Q and B.</summary>
        public static RankInfo minNormSolveInPlace(ref doubleMxN A_to_Q, ref doubleMxN B, ref doubleMxN X)
        {
            return minNormSolveInPlace(ref A_to_Q, ref B, ref X, (double)(-1));
        }
    }
}
